// ══════════════════════════════════════════════════
// NORMALISER SOURCE — Drive ou Gmail (v3)
// Détecte la source par champs structurels Gmail/Drive
// La récupération des binaires est déléguée aux nœuds suivants
// ══════════════════════════════════════════════════
const item = $input.first().json;
const binary = $input.first().binary || {};

// Gmail → toujours: threadId, historyId, labels, payload
// Drive → toujours: webViewLink (et id sans threadId)
const isGmail = !!(item.threadId || item.historyId || Array.isArray(item.labels));

let fileData = {};

// ── SOURCE: GOOGLE DRIVE ───────────────────────────
if (!isGmail) {
  if (!item.id || !item.mimeType) {
    throw new Error('Source Drive invalide — champs id/mimeType manquants: ' + JSON.stringify(Object.keys(item)));
  }
  fileData = {
    source:   'DRIVE',
    fileId:   item.id,
    fileName: item.name || 'document.pdf',
    mimeType: item.mimeType,
    fileUrl:  item.webViewLink || ''
  };
}

// ── SOURCE: GMAIL ──────────────────────────────────
if (isGmail) {
  // Extraire le From depuis les headers si absent au niveau racine
  let fromAddress = item.from || '';
  if (!fromAddress && item.payload?.headers) {
    const h = item.payload.headers.find(h => h.name.toLowerCase() === 'from');
    fromAddress = h?.value || '';
  }

  // Extraire le sujet
  let subject = item.subject || '';
  if (!subject && item.payload?.headers) {
    const h = item.payload.headers.find(h => h.name.toLowerCase() === 'subject');
    subject = h?.value || '';
  }

  fileData = {
    source:       'GMAIL',
    fileId:       'gmail_' + item.id,
    _gmailId:     item.id,          // ID pur pour le nœud Gmail natif
    fileName:     `facture_email_${item.id}.pdf`, // sera mis à jour après téléchargement
    mimeType:     'application/pdf',
    fileUrl:      '',
    emailFrom:    fromAddress,
    emailSubject: subject
  };
}

return [{ json: fileData, binary }];

// ══════════════════════════════════════════════════
// EXTRAIRE PIÈCE JOINTE GMAIL
// Le nœud Gmail "get" a téléchargé les attachments
// On choisit le PDF (ou premier binaire disponible)
// ══════════════════════════════════════════════════
const meta   = $('⚙️ Normaliser Source').first().json;
const binary = $input.first().binary || {};

const attachKeys = Object.keys(binary);

if (attachKeys.length === 0) {
  throw new Error(
    `Aucune pièce jointe téléchargée pour cet email.\n` +
    `De: ${meta.emailFrom || 'inconnu'}\n` +
    `Sujet: ${meta.emailSubject || 'inconnu'}\n` +
    `Conseil: Vérifier que l'email contient bien un PDF en pièce jointe (pas inline).`
  );
}

// Priorité: PDF > image > autre
const pdfKey = attachKeys.find(k => (binary[k]?.mimeType || '').includes('pdf'));
const imgKey = attachKeys.find(k => (binary[k]?.mimeType || '').startsWith('image/'));
const bestKey = pdfKey || imgKey || attachKeys[0];

const chosen = binary[bestKey];
console.log(`PJ choisie: ${bestKey} — ${chosen?.mimeType} — ${chosen?.fileName}`);

return [{
  json: {
    ...meta,
    fileName:    chosen?.fileName || meta.fileName,
    mimeType:    chosen?.mimeType || 'application/pdf',
    _binaryKey:  bestKey
  },
  binary: {
    data: chosen
  }
}];

// 1. Récupérer le texte de Gemini
const item = $input.first().json;
const rawText = item.content?.parts?.[0]?.text;

// 2. Nettoyage et Parsing du JSON de Gemini
const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleaned);

// 3. Récupérer les métadonnées du nœud "Normaliser Source"
const sourceItem = $items("⚙️ Normaliser Source")[0]?.json || $items()[0]?.json || {};

// 4. Fusion et Normalisation finale
return [{
  json: {
    ...parsed,
    // Normalisation du bénéficiaire
    beneficiaire: (parsed.beneficiaire && parsed.beneficiaire.trim() !== "")
                  ? parsed.beneficiaire.toUpperCase()
                  : "ANONYME",
    // Ajout des métadonnées techniques (provenant de Normaliser Source)
    _fileId: sourceItem.fileId || "INCONNU",
    _source: sourceItem.source || "INCONNUE",
    _fileName: sourceItem.fileName || "INCONNU",
    _originalUrl: sourceItem.fileUrl || ''
  }
}];

// ══════════════════════════════════════════════════════════════
// NORMALISATION FISCALE QUÉBÉCOISE
// ══════════════════════════════════════════════════════════════
const items = $input.all();

return items.map(item => {
  const data = item.json;

  // 1. Nettoyage du nom de fichier
  let cleanName = (data.clean_filename || "DOCUMENT").toString();
  cleanName = cleanName
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // Enlève accents
    .replace(/[^a-zA-Z0-9._-]/g, "_")                 // Caractères autorisés
    .replace(/_{2,}/g, "_")                           // Évite __
    .toUpperCase()
    .substring(0, 50);                                // Limite longueur

  // 2. Gestion bénéficiaire
  const beneficiaire = (data.beneficiaire && data.beneficiaire.trim() !== "")
    ? data.beneficiaire.toUpperCase()
    : "ANONYME";

  // 3. Calculs Fiscaux (Priorité aux données existantes, sinon calcul)
  let ttc = parseFloat(data.montant_ttc) || 0;
  let net = parseFloat(data.montant_net) || 0;
  let tps = parseFloat(data.tps) || 0;
  let tvq = parseFloat(data.tvq) || 0;

  // Si catégorie AUTONOME et que les taxes sont à 0, on calcule tout
  if (data.categorie === "AUTONOME" && ttc > 0 && net === 0) {
    net = ttc / 1.14975;
    tps = net * 0.05;
    tvq = net * 0.09975;
  }

  // 4. Retour des données consolidées
  return {
    json: {
      ...data,
      clean_filename: cleanName,
      beneficiaire: beneficiaire,
      montant_net: Math.round(net * 100) / 100,
      tps: Math.round(tps * 100) / 100,
      tvq: Math.round(tvq * 100) / 100,
      montant_ttc: Math.round(ttc * 100) / 100,
      date_journal: data.date || new Date().toISOString().split('T')[0],
      is_fiscal: ["PRO", "AUTONOME"].includes(data.categorie)
    }
  };
});

/**
 * ROUTEUR FISCAL V5 - GED SENTINELLE
 * Variables d'environnement $env. (Community Edition)
 */

const input = $input.first().json;

// --- 1. NETTOYAGE DES DONNÉES DE BASE ---
let emetteur = (input.emetteur || "INCONNU").toUpperCase().replace(/[^A-Z0-9]/g, "_");
let beneficiaire = (input.beneficiaire || "ANONYME").toUpperCase();
let categorie = (input.categorie || "PRIV_VIE").toUpperCase();
let montant_ttc = parseFloat(input.montant_ttc) || 0;

// --- 2. LOGIQUE FISCALE & CALCUL DES TAXES ---
let montant_net = 0;
let tps = 0;
let tvq = 0;
let note_fiscale = "";

if (categorie === "AUTONOME" && montant_ttc > 0) {
    montant_net = montant_ttc / 1.14975;
    tps = montant_net * 0.05;
    tvq = montant_net * 0.09975;
    note_fiscale = "DÉDUCTIBLE 100% (CTI/RTI)";
}
else if (categorie === "PRO") {
    note_fiscale = "REMBOURSABLE EMPLOYEUR";
}
else if (input.flag_mixte) {
    note_fiscale = "⚠️ À VENTILER (MARCHAND GÉNÉRALISTE)";
}

// --- 3. OPTIMISATION DU NOM DE FICHIER ---
let cleanName = input.clean_filename || "";
cleanName = cleanName
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .replace(/_{2,}/g, "_")
    .toUpperCase();

// --- 4. DÉTERMINATION DES DOSSIERS DRIVE ---
// IDs depuis variables d'environnement ($env. — Community Edition)
const ID_PARENT_IMPOTS  = $env.GED_IMPOTS_PARENT_ID;
const ID_PARENT_ARCHIVE = $env.GED_ARCHIVE_FOLDER_ID;

const isFiscal = ['PRO', 'AUTONOME', 'MAISON_BUREAU'].includes(categorie);
const fiscalYear = new Date().getFullYear();
const targetFolderName = isFiscal ? `Impôts ${fiscalYear}` : "_GED_ARCHIVE";

// --- 5. FLAG VALIDATION ---
const _needsValidation = input.flag_mixte === true || (input.confiance || '').toUpperCase() === 'BASSE';

// --- 5. RETOUR ---
return [{
    json: {
        ...input,
        date: input.date || new Date().toISOString().split('T')[0],
        emetteur: emetteur,
        categorie: categorie,
        sous_categorie: (input.sous_categorie || "DIVERS").toUpperCase(),
        beneficiaire: beneficiaire,
        montant_net: Number(montant_net.toFixed(2)),
        tps: Number(tps.toFixed(2)),
        tvq: Number(tvq.toFixed(2)),
        montant_ttc: Number(montant_ttc.toFixed(2)),
        note_fiscale: note_fiscale,
        clean_filename: cleanName,
        _isFiscal: isFiscal,
        _targetFolderName: targetFolderName,
        _impotsParentId: ID_PARENT_IMPOTS,
        _archiveFolderId: ID_PARENT_ARCHIVE,
        _needsValidation: _needsValidation,
        dossier_destination: isFiscal ? "PROFESSIONNEL" : "PERSONNEL"
    }
}];

const d = $input.first().json;

return[{
  json: {
    ...d,
    _validationMethod: 'AUTO_IA',
    _finalFileName: d.clean_filename || "DOCUMENT_SANS_NOM.pdf",
    _sheetRow: {
      Date:          d.date || d.date_journal || '',
      Emetteur:      d.emetteur || 'INCONNU',
      Categorie:     d.categorie || 'INCONNUE',
      Sous_Categorie:d.sous_categorie || '',
      Objet:         (d.objet && d.objet !== "") ? d.objet.toUpperCase() : (d.sous_categorie || 'DIVERS'),
      Beneficiaire:  d.beneficiaire || 'ANONYME',
      Montant_Net:   d.montant_net || 0,
      TPS:           d.tps || 0,
      TVQ:           d.tvq || 0,
      Montant_TTC:   d.montant_ttc || 0,
      Lien_Drive:    '',
      Source:        d._source || 'INCONNUE'
    }
  }
}];

const inputData = $input.first().json;
let targetFolderId = inputData.id;

let invoiceData = {};
try {
  invoiceData = $('✅ Approbation Automatique').first().json;
} catch (e) {
  throw new Error("Le nœud '✅ Approbation Automatique' est introuvable.");
}

if (!targetFolderId) {
  targetFolderId = invoiceData._archiveFolderId;
}

return[{
  json: {
    ...invoiceData,
    _resolvedFolderId: targetFolderId,
    _finalFileName: invoiceData.clean_filename || "DOCUMENT_SANS_NOM.pdf"
  }
}];

const d = $('✅ Approbation Automatique').first().json;
const driveResult = $('☁️ Archiver Fichier Renommé').first().json;
const driveLink = driveResult.webViewLink || driveResult.webContentLink || '';

const row = {
  ...d._sheetRow,
  Lien_Drive: driveLink
};
return [{ json: { ...d, _sheetRow: row, _driveLink: driveLink } }];
